---RefreshUI
---@param data table leftPlayerId leftInfo rightPlayerId rightInfo positionWheel matchResultIndex inBattle
function PVPArenaBattleLiveCell:RefreshUI(data)
    local leftPlayerId     = checkInt(data.leftPlayerId)
    local rightPlayerId    = checkInt(data.rightPlayerId)
    local leftScore        = checkInt(data.leftScore)
    local rightScore       = checkInt(data.rightScore)
    local isShowScore      = leftScore > 0 or rightScore > 0

    KTool.SetActive(self.ImgBattle.gameObject, not isShowScore)
    KTool.SetActive(self.ScoreGroup.gameObject, isShowScore)

    local leftIsLoser = leftScore < rightScore
    local rightIsLoser = rightScore < leftScore
    self:RefreshPVPArenaPlayerInfoNode(self.Left.gameObject, data.leftInfo, leftPlayerId, leftIsLoser)
    self:RefreshPVPArenaPlayerInfoNode(self.Right.gameObject, data.rightInfo, rightPlayerId, rightIsLoser)

    if isShowScore then
        self.TxtNumL.text = leftScore
        self.TxtNumL.color = XLuaUtils.HexToColor(leftIsLoser and "#9a999a" or "#ff2458")

        self.TxtNumR.text = rightScore
        self.TxtNumR.color = XLuaUtils.HexToColor(rightIsLoser and "#9a999a" or "#ff2458")
    end

end

---RefreshPVPArenaPlayerInfoNode
---@param go UnityEngine.GameObject 配置 PVPArenaPlayerInfoNode的游戏对象
---@param info table  PVPArenaDojo 中单条 比赛选手数据
---@param playerId number 玩家id
---@param isShowBlack boolean 是否遮盖
function PVPArenaBattleLiveCell:RefreshPVPArenaPlayerInfoNode(go, info, playerId, isShowBlack)
    ---@type PVPArenaPlayerInfoNode
    local env = CfUtils.GetLuaScr(go, PVPArenaPlayerInfoNodePath)
    if isNull(env) then return end
    env:RefreshUI(info, playerId, isShowBlack)
end

